const src = 'https://pub-2534e921bf9c4314addcd4d8a6e98b7b.r2.dev/objects/polyhaven/glb/antique_ceramic_vase_01.glb';
const bytes = new Uint8Array(await (await fetch(src)).arrayBuffer());
const slotRes = await fetch('https://three.ws/api/print/upload', { method: 'POST', headers: { 'content-type': 'application/json', 'x-forge-client': 'x-content-trial-materialize' }, body: JSON.stringify({ content_type: 'model/gltf-binary', size_bytes: bytes.length }) });
const slot = await slotRes.json();
if (!slotRes.ok) throw new Error(`upload slot HTTP ${slotRes.status}: ${JSON.stringify(slot)}`);
const put = await fetch(slot.upload_url, { method: 'PUT', headers: slot.headers || { 'content-type': 'model/gltf-binary' }, body: bytes });
if (!put.ok) throw new Error(`PUT to storage HTTP ${put.status}`);
const quoteRes = await fetch('https://three.ws/api/print/quote', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ glbUrl: slot.public_url, materialId: 'resin-standard', targetHeightMm: 120, country: 'US' }) });
const q = await quoteRes.json();
if (!quoteRes.ok) throw new Error(`quote HTTP ${quoteRes.status}: ${JSON.stringify(q).slice(0, 300)}`);
if (q.report?.manifold !== true || q.report?.watertight !== true) throw new Error(`the uploaded mesh was not checked as printable: ${JSON.stringify(q.report).slice(0, 300)}`);
if (!(q.quote?.total > 0) || q.quote.currency !== 'USDC' || q.quote.chain !== 'solana' || !q.token) throw new Error(`no signed USDC-on-Solana price: ${JSON.stringify(q.quote).slice(0, 300)}`);
console.log(`uploaded ${bytes.length} bytes to ${slot.public_url}; manifold, watertight, score ${q.report.score}; ${q.quote.lines.map((l) => `${l.id} ${l.amount}`).join(', ')}; total ${q.quote.total} ${q.quote.currency} on ${q.quote.chain}, signed token valid ${q.expiresInSeconds}s`);
